let saveLeaderboard = function() {
  // Variables
  let d = new Date();
  let dd = d.getDate();
  let mm = d.getMonth()+1;
  const yyyy = d.getFullYear();
  if (dd<10) { dd='0'+dd; } 
  if (mm<10) { mm='0'+mm; }
  d = dd + '/' + mm + '/' + yyyy
  const db = firebase.firestore().collection("leaderboard").doc(audioname);
  let uidg = {}
  // Real shit
  uidg[firebase.auth().currentUser.uid] = {
  accuracy: accuracy_text.textContent.slice(0, -1),
  lbColor: document.getElementById('lbColorInp').value,
  score: error_text.textContent,
  timestamp: d,
  displayName: firebase.auth().currentUser.displayName
  }
  let sanitycheck = error_text.textContent < 4500
  if (firebase.auth().currentUser.displayName == null) {
    alert("Your score hasn't been saved because you haven't set your display name to something. Edit your profile settings if you want your score to appear on the leaderboard.")
  }
  if (sanitycheck) {
    db.get().then((doc) => {
    if (doc.exists) {
    if(doc.data()[firebase.auth().currentUser.uid]) {
      if (doc.data()[firebase.auth().currentUser.uid].score < uidg[firebase.auth().currentUser.uid].score) {
      db.set(uidg, { merge: true });
      loadLeaderboard();
      }
    } else { db.set(uidg, { merge: true }); loadLeaderboard() }
    } else {
          firebase.firestore().collection("leaderboard").doc(audioname).set({
          0: {
            displayName: '-',
            score: 0,
            accuracy: 0,
            timestamp: "-",
            lbColor: '#000000'
          }
        }).then(() => {
          console.log("Added ", audioname);
          saveLeaderboard();
          loadLeaderboard();
        }).catch((error) => {
          console.error(error)
        })
    }
    })
  } else {
    if (firebase.auth().currentUser.displayName != null) {
      window.location.href = 'https://youtube.com/watch/?v=dQw4w9WgXcQ'
    }
  }
}

/////////////////////////////////////////////////////////////////////////////////

let loadLeaderboard = function() {
  db.collection("leaderboard").doc(audioname).get().then((doc) => {
  const data = doc.data()
  let sortable = []
  for (var vehicle in data) {
  sortable.push([vehicle, data[vehicle]]);
}
  sortable.sort(function(a, b) {
  return b[1].score - a[1].score;
});
  let template = `
  <tbody><tr>
  <th>
    #
  </th>
  <th>
    Player
  </th>
  <th>
    Score
  </th>
  </tr></tbody>`;
  for (let i = 0; i < sortable.length; i++) {
    if (i < 10) {
    let pos = i + 1
    let daeta = sortable[i][1]
    let premium = false
    firebase.firestore().collection("leaderboard").doc("according").get().then((doc) => {
      data = doc.data()
      console.log(data[firebase.auth().currentUser.uid])
      Object.entries(data).forEach(uid => {
        firebase.firestore().collection("subscriptions").doc(`${uid[0]}`).get().then((doc) => {
          if (doc.exists && doc.data()["pro"]) {
            premium = true
          }
        })
      })
    })
    if (!premium) {
      template += `
      <tr class="driver leaderboard_all">
      <td class="position">${pos}</td>
      <td class="driver" style="border-left: 4px solid ${daeta.lbColor}">${daeta.displayName}<span>${daeta.timestamp}</span></td>
      <td class="gap"><span>${daeta.score}</span></td>
      </tr>
      `
    }}
    else {
      template += `
      <tr class="driver leaderboard_all">
      <td class="position">${pos}</td>
      <td class="driver" style="border-left: 4px solid ${daeta.lbColor}">${daeta.displayName}<img class="ktypepro" src="../ktypepro.svg"/><span>${daeta.timestamp}</span></td>
      <td class="gap"><span>${daeta.score}</span></td>
      </tr>
      `
    }
  }
  document.querySelector('.leaderboard').innerHTML = template;
  document.querySelector('.quote_copy').style.display = 'flex'
})
}

